/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PARTY_HIERARCHY
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PARTY   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_delta3
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PARTY_HK
   hashdiff    : SAT_PARTY_HIERARCHY_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CONTRACT_ID_INSURED_NAME))) as HUB_PARTY_HK
        , PARENT_NAME as REPORTING_PARENT_NAME
        , PARENT_CITY as REPORTING_PARENT_CITY_CODE
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|'))))) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REPORTING_PARENT_NAME end) as REPORTING_PARENT_NAME,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REPORTING_PARENT_CITY_CODE end) as REPORTING_PARENT_CITY_CODE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when REPORTING_PARENT_NAME is not null or REPORTING_PARENT_CITY_CODE is not null
                     then md5(upper(coalesce(cast(REPORTING_PARENT_NAME as varchar), '') || '|' || coalesce(cast(REPORTING_PARENT_CITY_CODE as varchar), '')))
                end as SAT_PARTY_HIERARCHY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_HIERARCHY_HASHDIFF is not null
